items.check_script:
# -*- coding: utf-8 -*-

import re

from items.common._base import BaseCheck


CHECK_COMMAND = 'free -m'


class Check(BaseCheck):
    USE_HOST_CONNECTION = True
    CONNECTION_METHOD = 'ssh'


    def parse_output(self, output):
        for line in (output or '').splitlines():
            parts = line.split()
            if not parts or parts[0].rstrip(':').lower() != 'mem':
                continue
            if len(parts) < 7:
                return {'failure_type': 'parse_failure', 'reason': 'free -m Mem row has fewer than 7 columns.'}
            try:
                total = float(parts[1])
                used = float(parts[2])
                available = float(parts[6])
            except Exception:
                return {'failure_type': 'parse_failure', 'reason': 'free -m memory value is not numeric.'}
            if total <= 0:
                return {'failure_type': 'parse_failure', 'reason': 'free -m total memory is zero.'}
            return {'memory_usage_percent': round(used / total * 100.0, 1), 'available_percent': round(available / total * 100.0, 1)}
        return {'failure_type': 'parse_failure', 'reason': 'free -m Mem row was not found.'}

    def evaluate(self, metrics, max_memory_percent, min_available_percent):
        if metrics.get('failure_type'):
            return 'fail'
        if metrics['memory_usage_percent'] > max_memory_percent:
            return 'fail'
        if metrics['available_percent'] < min_available_percent:
            return 'fail'
        return 'ok'

    def build_result(self, metrics, max_memory_percent, min_available_percent, status):
        criteria = 'ok: memory usage <= %.1f%% and available >= %.1f%%' % (max_memory_percent, min_available_percent)
        if metrics.get('failure_type'):
            return {'message': 'memory usage check failed.', 'results': metrics.get('reason', ''), 'criteria': criteria}
        results = 'memory_usage_percent=%.1f%%, available_percent=%.1f%%' % (metrics['memory_usage_percent'], metrics['available_percent'])
        message = 'memory usage check passed.' if status == 'ok' else 'memory usage check failed policy.'
        return {'message': message, 'results': results, 'criteria': criteria}

    def run(self):
        max_memory_percent = self.get_threshold_var('max_memory_percent', default=80.0, value_type='float')
        min_available_percent = self.get_threshold_var('min_available_percent', default=20.0, value_type='float')

        rc, output, error = self._ssh(CHECK_COMMAND)

        if rc != 0:
            metrics = {
                'failure_type': 'command_failure',
                'rc': rc,
                'reason': (error or output or 'command failed').strip(),
            }
        else:
            metrics = self.parse_output(output)

        status = self.evaluate(metrics, max_memory_percent, min_available_percent)
        result = self.build_result(metrics, max_memory_percent, min_available_percent, status)

        return self.result(
            status=status,
            message=result['message'],
            metrics=metrics,
            results=result['results'],
            criteria=result['criteria'],
        )


CHECK_CLASS = Check
